# --- benchmark ---

def parse_csv(text):
    rows = []
    row = []
    field = []
    quoted = False
    closed = False
    started = False
    skip_lf = False
    for char in text:
        if skip_lf:
            skip_lf = False
            if char == '\n':
                continue
        if quoted:
            if char == '"':
                quoted = False
                closed = True
            else:
                field.append(char)
        elif closed and char == '"':
            field.append('"')
            quoted = True
            closed = False
        elif char == ',':
            row.append(''.join(field))
            field = []
            closed = False
            started = False
        elif char == '\n' or char == '\r':
            if row or started or closed or field:
                row.append(''.join(field))
            rows.append(row)
            row = []
            field = []
            closed = False
            started = False
            skip_lf = char == '\r'
        elif closed:
            raise ValueError('Unexpected character after closing quote')
        elif char == '"':
            if started:
                raise ValueError('Quote inside unquoted field')
            quoted = True
            started = True
        else:
            field.append(char)
            started = True
    if quoted:
        raise ValueError('Unterminated quoted field')
    if row or started or closed or field:
        row.append(''.join(field))
        rows.append(row)
    return rows


def csv_records(text):
    rows = parse_csv(text)
    if not rows:
        return []
    header = rows[0]
    records = []
    for values in rows[1:]:
        if not values:
            continue
        if len(values) != len(header):
            raise ValueError('CSV field count differs from header')
        records.append(dict(zip(header, values)))
    return records


def csv_row(fields):
    encoded = []
    for field in fields:
        if (len(fields) == 1 and field == '') or ',' in field or '"' in field or '\n' in field or '\r' in field:
            field = '"' + field.replace('"', '""') + '"'
        encoded.append(field)
    return ','.join(encoded) + '\n'

output = [csv_row(['id', 'name', 'note'])]
rows = 0
missing = 0
for row in csv_records(TEXT):
    name = row['name'].strip()
    note = row['note'].strip().replace('\n', ' ')
    if not name:
        missing += 1
        continue
    output.append(csv_row([row['id'], name, note]))
    rows += 1
cleaned = ''.join(output)
parsed = parse_csv(cleaned)
assert len(parsed) == rows + 1
print(rows, missing, len(cleaned), sum(len(row[2]) for row in parsed[1:]))
